base_colors = [(181, 83, 40), (45, 50, 184), (187, 187, 53), (184, 70, 162), 
               (184, 50, 50), (146, 70, 192), (110, 156, 66), (84, 138, 210)]

ground_colors = [(110, 156, 66), (66, 114, 194), (198, 108, 58), (66, 72, 200), 
