    objects.clear()

    player = find_mc_objects(obs, [objects_colors["orange1"], objects_colors["orange2"], objects_colors["orange3"], objects_colors["orange4"]], miny=12, maxy=174)
    for bb in player:
        if bb[3] > 5 and bb[3] > 12 and bb[3] < 17:
            objects.append(Player(*bb))

    if len(player) == 0: 
        mare = find_objects(obs, objects_colors["orange1"])
        for bb in mare:
            if bb[3] > 7:
                objects.append(Fire_Mare(*bb))

    lyssa = find_mc_objects(obs, [objects_colors["red1"], objects_colors["pink1"], objects_colors["purple1"], objects_colors["purple2"], objects_colors["blue1"], objects_colors["blue2"], objects_colors["blue3"], objects_colors["green1"]], miny=12, maxy=175, size=(7,16), tol_s=3)
    for bb in lyssa:
        objects.append(Lyssa(*bb))

    slayers = find_mc_objects(obs, [objects_colors["green2"], objects_colors["blue4"], objects_colors["blue5"], objects_colors["blue6"], objects_colors["purple3"], objects_colors["purple4"], objects_colors["pink2"], objects_colors["red2"]], miny=12, maxy=173)
    for bb in slayers:
        objects.append(Slayers(*bb))

    spider = find_objects(obs, objects_colors["white"], size=(8,9), tol_s=2, miny=12, maxy=174)
    for bb in spider:
        objects.append(Spider(*bb))

    star = find_objects(obs, objects_colors["white"], size=(3,4), tol_s=2, miny=12, maxy=174)
    for bb in star:
        objects.append(Star(*bb))

    life = find_objects(obs, objects_colors["green3"], size=(8,9), tol_s=2, miny=12, maxy=174)
    for bb in life:
        if bb[2] < 7:
            objects.append(Life(*bb))
        else:
            objects.append(Weapon(*bb))

    beast = find_mc_objects(obs, [objects_colors["orange6"], objects_colors["red3"]], miny=12, maxy=173)
    for bb in beast:
        objects.append(Beast(*bb))

    wall = find_objects(obs, objects_colors["orange5"], miny=12, maxy=75)
    for bb in wall:
        objects.append(Wall(*bb))

    weapon = find_objects(obs, objects_colors["yellow1"], miny=12, maxy=173)
    for bb in weapon:
        if bb[3] > 1:
            objects.append(Weapon(*bb))

    if len(beast) != 0:
        e_weapon = find_objects(obs, objects_colors["pink1"], miny=60, maxy=173)
        e_weapon.extend(find_objects(obs, objects_colors["pink2"], miny=60, maxy=173))
        e_weapon.extend(find_objects(obs, objects_colors["pink3"], miny=60, maxy=173))
        e_weapon.extend(find_objects(obs, objects_colors["pink4"], miny=60, maxy=173))
