                               tol_s=2, miny=61, maxx=129)
    for el in unpicked_bait + flying_bait:
        objects.append(Bait(*el))

    # Balloon
    minx = [43, 75, 107] 
    maxx = [53, 85, 117]
    for i in range(6):
        balloon = find_objects(obs, objects_colors['balloon'][i],
                               minx=minx[i//2], miny=61, maxx=maxx[i//2], maxy=175)
        for el in balloon:
            objects.append(Balloon(*el))

    # Enemy
